function validate([candiesCount, queries]) {
  if (!Array.isArray(candiesCount) || candiesCount.length < 1 || candiesCount.length > 100000) return 'candiesCount needs 1 to 10^5 values.';
  if (candiesCount.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each candy count is an integer from 1 to 10^5.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 3 || !q.every(Number.isInteger)) return 'Each query is [favoriteType, favoriteDay, dailyCap].';
    if (q[0] < 0 || q[0] >= candiesCount.length) return 'favoriteType must be a valid type index.';
    if (q[1] < 0 || q[1] > 1000000000) return 'favoriteDay is between 0 and 10^9.';
    if (q[2] < 1 || q[2] > 1000000000) return 'dailyCap is between 1 and 10^9.';
  }
  return null;
}

