  for (const count of candiesCount) {
    prefix.push(prefix[prefix.length - 1] + count);
  }

  const answer = [];
  for (const [favoriteType, favoriteDay, dailyCap] of queries) {
    const earliest = Math.floor(prefix[favoriteType] / dailyCap);
    const latest = prefix[favoriteType + 1] - 1;
    answer.push(earliest <= favoriteDay && favoriteDay <= latest);
