function canEat(candiesCount, queries) {
  // Candy number j (in eating order) has type owner[j].
  const owner = [];
  candiesCount.forEach((count, type) => { for (let c = 0; c < count; c++) owner.push(type); });
  const total = owner.length;
  return queries.map(([type, day, cap]) => {
    // Simulate day by day the range [low, high] of amounts that can be eaten before the day.
    let low = 0, high = 0;
    for (let d = 0; d < day; d++) {
      if (low >= total) return false;
      low = low + 1;
      high = Math.min(high + cap, total);
    }
    if (low >= total) return false;
    // On this day some candy with index in [low, min(high + cap, total) - 1] can be eaten.
    for (let j = low; j < Math.min(high + cap, total); j++) if (owner[j] === type) return true;
    return false;
  });
}

