function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 4);
    const candiesCount = Array.from({ length: n }, () => int(1, 5));
    const total = candiesCount.reduce((a, b) => a + b, 0);
    const queries = Array.from({ length: int(1, 6) }, () => {
      const cap = rand() < 0.15 ? int(1, 1000000000) : int(1, total + 1);
      return [int(0, n - 1), int(0, total + 2), cap];
    });
    return [candiesCount, queries];
  }
  const n = int(1500, 2000);
  const candiesCount = Array.from({ length: n }, () => rand() < 0.5 ? int(1, 100) : int(1, 100000));
  const prefix = [0];
  for (const count of candiesCount) prefix.push(prefix[prefix.length - 1] + count);
  const queries = Array.from({ length: 2000 }, () => {
    const type = int(0, n - 1);
    const pick = rand();
    const cap = pick < 0.3 ? int(1, 10) : pick < 0.7 ? int(1, 100000) : int(1, 1000000000);
    const earliest = Math.floor(prefix[type] / cap);
    const latest = prefix[type + 1] - 1;
    let day = rand() < 0.2 ? int(0, 1000000000) : int(Math.max(0, earliest - 3), latest + 3);
    if (day > 1000000000) day = 1000000000;
    return [type, day, cap];
  });
  return [candiesCount, queries];
}
